class TaskViewModel(
    application: Application,
    private val repository: TaskRepository
) : AndroidViewModel(application) {

    val allTasks: Flow<List<Task>> = repository.allTasks

    fun saveTask(task: Task) {
        viewModelScope.launch {
            val newId = repository.insert(task)
            val taskId = if (task.id == 0) newId.toInt() else task.id
            val ctx = getApplication<Application>().applicationContext

            if (task.reminderTime != null && task.reminderTime > System.currentTimeMillis()) {
                ReminderScheduler.schedule(ctx, taskId, task.title, task.reminderTime)
            } else {
                ReminderScheduler.cancel(ctx, taskId)
            }
        }
    }

    fun deleteTask(task: Task) {
        viewModelScope.launch {
            repository.delete(task)
            ReminderScheduler.cancel(getApplication<Application>().applicationContext, task.id)
        }
    }
}

